import pathlib, sys
root = pathlib.Path.cwd().resolve()
sys.path.insert(0, str(root))
import more_itertools
assert pathlib.Path(more_itertools.__file__).resolve() == root / 'more_itertools/__init__.py'
from more_itertools import chunked
cases = 0
for n in range(1, 8):
    for length in range(31):
        data = list(range(length))
        expected = [data[i:i+n] for i in range(0, length, n)]
        assert list(chunked(iter(data), n)) == expected, (n, length, 'non-strict')
        yielded = []
        error = None
        try:
            for value in chunked(iter(data), n, strict=True):
                yielded.append(value)
        except ValueError as exc:
            error = exc
        if length % n:
            assert error is not None, (n, length, 'missing ValueError')
            assert yielded == expected[:-1], (n, length, 'partial chunk escaped')
        else:
            assert error is None and yielded == expected, (n, length, 'divisible')
        cases += 1
assert list(chunked(iter([]), 3, strict=True)) == []
assert list(chunked('abc', None)) == [['a', 'b', 'c']]
assert list(chunked('abc', 0)) == []
for n in (-1, -5):
    try:
        list(chunked('abc', n))
    except ValueError:
        pass
    else:
        raise AssertionError(('negative n accepted', n))
try:
    list(chunked('abc', None, strict=True))
except ValueError:
    pass
else:
    raise AssertionError('None n accepted in strict mode')
print('PASS independent chunked acceptance:', cases, 'size/length pairs + 6 boundary checks')
